#!/usr/bin/env bash
set -uo pipefail

# The emulator action runs each script line in a separate shell. Keep the test
# status and screenshot loop together so failures still leave visual evidence.
test_status=0
./gradlew :app:connectedDebugAndroidTest --no-daemon || test_status=$?
mkdir -p app/build/device-screenshots
for name in explore battle trap preparation compact shop equipment wall-depth third-person enemy-damage player-damage victory trap-cue-0 trap-cue-1 trap-cue-2 trap-cue-3 trap-cue-4 compact-victory compact-cue npc-encounter chest-encounter chest-ambush merchant-encounter sell-equipped sell-removed trap-auto-success trap-auto-failure weapon-sword weapon-spear weapon-hammer weapon-claw weapon-whip enemy-knight enemy-bat enemy-boss fine-heal fine-door fine-inheritance fine-inventory-top fine-inventory-bottom fine-atlas retreat-confirm retreat-result equipment-empty equipment-body-layout death-result compact-death compact-equipment growth-grid growth-empty shop-grid shop-purchased quantity-grid sell-grid walk-0 walk-1 walk-2 walk-3 walk-4 turn-0 turn-1 turn-2 turn-3 smooth-corridor compact-growth compact-shop equipment-stays equipment-continuous menu-equipment menu-inventory menu-shop menu-growth menu-bank menu-help critical-enemy critical-player animated-death scene-caption motion-sword-0 motion-sword-1 motion-sword-2 motion-spear-0 motion-spear-1 motion-spear-2 motion-hammer-0 motion-hammer-1 motion-hammer-2 motion-claw-0 motion-claw-1 motion-claw-2 motion-whip-0 motion-whip-1 motion-whip-2 motion-slime-0 motion-slime-1 motion-slime-2 motion-bat-0 motion-bat-1 motion-bat-2 motion-knight-0 motion-knight-1 motion-knight-2 motion-boss-0 motion-boss-1 motion-boss-2 shop-comparison records-clean entry-redesign defense-controls action-attack-0 action-attack-1 action-attack-2 action-strong-0 action-strong-1 action-strong-2 action-guard-0 action-guard-1 action-guard-2 action-dodge-0 action-dodge-1 action-dodge-2 dungeon-toolbar dungeon-equipment dungeon-stats turn-attack turn-defense level-up level-up-dismissed dead-end dead-end-cleared shop-red-name shop-gold-toast top-explore-menus top-combat-menus obstacle-0-0 obstacle-0-1 obstacle-0-2 obstacle-1-0 obstacle-1-1 obstacle-1-2 obstacle-2-0 obstacle-2-1 obstacle-2-2 obstacle-3-0 obstacle-3-1 obstacle-3-2 obstacle-4-0 obstacle-4-1 obstacle-4-2 tap-only-combat gold-center chest-loot full-guard-zero training-menu training-battle training-merchant training-npc training-trap blades-raised blades-retracted blades-jump beam-descending beam-crouch blades-compact beam-compact; do
  adb pull "/sdcard/Download/mapexit-${name}.png" "app/build/device-screenshots/${name}.png" || true
done
exit "${test_status}"
